import { FormEvent, useEffect, useState } from "react";

const API = import.meta.env.VITE_API_URL ?? "http://localhost:3000";
type Role = "REQUESTER" | "IT_STAFF" | "ADMINISTRATOR";
type User = { id: number; name: string; email: string; role: Role; isActive: boolean };
type Reference = { id: number; name: string };
type Attachment = { id: number; originalFilename: string; mimeType: string; byteSize: number; createdAt?: string; removedAt: string | null; removalReason: string | null };
type Comment = { id: number; content: string; createdAt?: string; author?: { id: number; name: string; role: string } };
type Ticket = { id: number; ticketNumber: string; summary: string; description?: string; currentStatus: string; requestedPriority: string; itPriority?: string; category?: Reference; relatedSystem?: Reference; owner?: { id: number; name: string; role?: string } | null; attachments?: Attachment[]; publicComments?: Comment[]; internalNotes?: Comment[]; requester?: { id: number; name: string; email?: string }; problemAppearsResolvedAt?: string | null; createdAt?: string; updatedAt?: string };
type Pagination = { page: number; pageSize: number; totalItems: number; totalPages: number };
type QueueItem = Ticket & { requester: { id: number; name: string }; createdAt: string; updatedAt: string };

const STATUSES = ["NEW", "OPEN", "IN_PROGRESS", "WAITING_FOR_REQUESTER", "RESOLVED", "CLOSED", "REOPENED", "CANCELLED"];
const PRIORITIES = ["LOW", "MEDIUM", "HIGH"];
const ROLES: Role[] = ["REQUESTER", "IT_STAFF", "ADMINISTRATOR"];

class ApiError extends Error {
  constructor(message: string, readonly code = "SERVER_ERROR", readonly status = 500) { super(message); }
}

async function api(path: string, token: string, options: RequestInit = {}) {
  const response = await fetch(API + path, { ...options, headers: { ...options.headers, "Content-Type": "application/json", ...(token ? { Authorization: `Bearer ${token}` } : {}) } });
  const data = response.status === 204 ? null : await response.json().catch(() => null);
  if (!response.ok) throw new ApiError(data?.error ?? "Request failed.", data?.code ?? "SERVER_ERROR", response.status);
  return data;
}

async function upload(path: string, token: string, file: File) {
  const form = new FormData(); form.set("file", file);
  const response = await fetch(API + path, { method: "POST", body: form, headers: { Authorization: `Bearer ${token}` } });
  const data = await response.json().catch(() => null);
  if (!response.ok) throw new ApiError(data?.error ?? "Upload failed.", data?.code ?? "SERVER_ERROR", response.status);
  return data;
}

function formatDate(value?: string) { return value ? new Intl.DateTimeFormat(undefined, { dateStyle: "medium", timeStyle: "short" }).format(new Date(value)) : "—"; }
function safeMessage(reason: unknown, fallback: string) { return reason instanceof Error ? reason.message : fallback; }
function errorMessage(reason: unknown, fallback: string) { return reason instanceof ApiError && reason.code === "FORBIDDEN" ? "You do not have permission to view this area." : safeMessage(reason, fallback); }

export default function App() {
  const [token, setToken] = useState(sessionStorage.getItem("toktickit.token") ?? "");
  const [user, setUser] = useState<User | null>(null);
  const [mustChangePassword, setMustChangePassword] = useState(false);
  const [page, setPage] = useState<"home" | "queue" | "users">("home");
  const [error, setError] = useState("");

  useEffect(() => {
    if (!token) return;
    api("/api/auth/me", token).then((data) => { setUser(data.user); setMustChangePassword(Boolean(data.mustChangePassword)); }).catch(() => { setToken(""); setUser(null); sessionStorage.removeItem("toktickit.token"); });
  }, [token]);

  if (!token) return <Login onLogin={(newToken, nextUser, nextMustChange) => { sessionStorage.setItem("toktickit.token", newToken); setToken(newToken); setUser(nextUser); setMustChangePassword(nextMustChange); }} />;
  if (!user) return <main className="container py-5"><p role="status" aria-live="polite">Loading your account…</p></main>;
  if (mustChangePassword) return <Password token={token} onDone={() => api("/api/auth/me", token).then((data) => { setUser(data.user); setMustChangePassword(Boolean(data.mustChangePassword)); })} />;

  const logout = async () => { try { await api("/api/auth/logout", token, { method: "POST" }); } finally { sessionStorage.removeItem("toktickit.token"); setToken(""); setUser(null); } };
  const navigate = (next: "home" | "queue" | "users") => { setError(""); setPage(next); };
  return <div className="min-vh-100 toktickit-page"><header className="border-bottom bg-white"><div className="container py-3 d-flex gap-3 align-items-center flex-wrap"><strong className="me-auto">TokTickIT <span className="toktickit-text">IT Service Desk</span><small className="d-block text-secondary">{user.name} · {user.role.replace("_", " ")}</small></strong><nav aria-label="Primary navigation" className="d-flex gap-2 flex-wrap">{user.role !== "REQUESTER" && <button type="button" className="btn btn-toktickit-outline" onClick={() => navigate("queue")}>Ticket Queue</button>}{user.role === "ADMINISTRATOR" && <button type="button" className="btn btn-toktickit-outline" onClick={() => navigate("users")}>User Management</button>}<button type="button" className="btn btn-outline-secondary" onClick={() => void logout()}>Logout</button></nav></div></header><main className="container py-5">{error && <div className="alert alert-danger" role="alert">{error}</div>}{page === "queue" && user.role !== "REQUESTER" ? <Queue token={token} /> : page === "users" && user.role === "ADMINISTRATOR" ? <Users token={token} onError={setError} /> : user.role === "REQUESTER" ? <Requester token={token} onError={setError} /> : <section className="card shadow-sm border-0"><div className="card-body p-4"><h1 className="h3">Welcome, {user.name}</h1><p className="text-secondary">Your authenticated {user.role.replace("_", " ")} workspace is ready.</p></div></section>}</main></div>;
}

function Login({ onLogin }: { onLogin: (token: string, user: User, mustChangePassword: boolean) => void }) {
  const [email, setEmail] = useState(""); const [password, setPassword] = useState(""); const [error, setError] = useState(""); const [submitting, setSubmitting] = useState(false);
  const submit = async (event: FormEvent) => { event.preventDefault(); setError(""); setSubmitting(true); try { const data = await api("/api/auth/login", "", { method: "POST", body: JSON.stringify({ email, password }) }); onLogin(data.session.token, data.user, Boolean(data.mustChangePassword)); } catch (reason) { setError(safeMessage(reason, "Unable to sign in.")); } finally { setSubmitting(false); } };
  return <main className="container py-5" style={{ maxWidth: 520 }}><section className="card shadow-sm border-0"><div className="card-body p-4"><h1 className="h3">TokTickIT Login</h1><form onSubmit={submit} aria-busy={submitting}><div><label className="form-label mt-3" htmlFor="login-email">Email</label><input id="login-email" className="form-control" type="email" autoComplete="username" value={email} onChange={(event) => setEmail(event.target.value)} required /></div><div><label className="form-label mt-3" htmlFor="login-password">Password</label><input id="login-password" className="form-control" type="password" autoComplete="current-password" value={password} onChange={(event) => setPassword(event.target.value)} required /></div>{error && <div className="alert alert-danger mt-3" role="alert">{error}</div>}{submitting && <div className="text-secondary mt-3" role="status" aria-live="polite">Signing in…</div>}<button type="submit" className="btn btn-toktickit-primary mt-3" disabled={submitting}>{submitting ? "Signing in…" : "Sign in"}</button></form></div></section></main>;
}

function Password({ token, onDone }: { token: string; onDone: () => void | Promise<void> }) {
  const [password, setPassword] = useState(""); const [confirm, setConfirm] = useState(""); const [error, setError] = useState(""); const [submitting, setSubmitting] = useState(false);
  const validPassword = password.length >= 12 && /[A-Z]/.test(password) && /[a-z]/.test(password) && /[0-9]/.test(password);
  const submit = async (event: FormEvent) => { event.preventDefault(); setError(""); if (!validPassword) { setError("Password must be at least 12 characters and include upper-case, lower-case, and number characters."); return; } if (password !== confirm) { setError("New password and confirmation must match."); return; } setSubmitting(true); try { await api("/api/auth/change-password", token, { method: "POST", body: JSON.stringify({ newPassword: password, confirmation: confirm }) }); await onDone(); } catch (reason) { setError(safeMessage(reason, "Unable to change password.")); } finally { setSubmitting(false); } };
  return <main className="container py-5" style={{ maxWidth: 560 }}><section className="card shadow-sm border-0"><div className="card-body p-4"><h1 className="h3">Change your initial password</h1><p className="text-secondary">For security, choose a new password before entering the application.</p><form onSubmit={submit} aria-busy={submitting}><fieldset disabled={submitting} className="border-0 p-0 m-0"><div><label className="form-label mt-3" htmlFor="new-password">New password</label><input id="new-password" className="form-control" type="password" autoComplete="new-password" value={password} onChange={(event) => setPassword(event.target.value)} aria-describedby="password-rules" required /></div><div><label className="form-label mt-3" htmlFor="confirm-password">Confirm password</label><input id="confirm-password" className="form-control" type="password" autoComplete="new-password" value={confirm} onChange={(event) => setConfirm(event.target.value)} required /></div></fieldset><div id="password-rules" className="form-text mt-3"><strong>Password rules</strong><ul className="mb-0"><li>At least 12 characters</li><li>At least one upper-case letter</li><li>At least one lower-case letter</li><li>At least one number</li></ul></div>{error && <div className="alert alert-danger mt-3" role="alert">{error}</div>}{submitting && <div className="text-secondary mt-3" role="status" aria-live="polite">Saving password…</div>}<button type="submit" className="btn btn-toktickit-primary mt-3" disabled={submitting}>{submitting ? "Saving password…" : "Save password"}</button></form></div></section></main>;
}

function Requester({ token, onError }: { token: string; onError: (message: string) => void }) {
  const [items, setItems] = useState<Ticket[]>([]); const [selected, setSelected] = useState<Ticket | null>(null); const [summary, setSummary] = useState(""); const [description, setDescription] = useState(""); const [createFile, setCreateFile] = useState<File | null>(null); const [message, setMessage] = useState(""); const [categories, setCategories] = useState<Reference[]>([]); const [systems, setSystems] = useState<Reference[]>([]); const [categoryId, setCategoryId] = useState(""); const [systemId, setSystemId] = useState(""); const [requestedPriority, setRequestedPriority] = useState("MEDIUM"); const [search, setSearch] = useState(""); const [categoryFilter, setCategoryFilter] = useState(""); const [systemFilter, setSystemFilter] = useState(""); const [priorityFilter, setPriorityFilter] = useState(""); const [statusFilter, setStatusFilter] = useState(""); const [sort, setSort] = useState("createdAt"); const [direction, setDirection] = useState("desc"); const [page, setPage] = useState(1); const [pageSize, setPageSize] = useState(10); const [pagination, setPagination] = useState<Pagination>({ page: 1, pageSize: 10, totalItems: 0, totalPages: 0 }); const [loading, setLoading] = useState(false); const [creating, setCreating] = useState(false);
  const load = async () => { setLoading(true); try { const params = new URLSearchParams({ page: String(page), pageSize: String(pageSize), sort, direction }); if (search.trim()) params.set("search", search.trim()); if (categoryFilter) params.set("categoryId", categoryFilter); if (systemFilter) params.set("relatedSystemId", systemFilter); if (priorityFilter) params.set("requestedPriority", priorityFilter); if (statusFilter) params.set("status", statusFilter); const data = await api(`/api/tickets?${params.toString()}`, token); setItems(data.items ?? []); setPagination(data.pagination ?? { page, pageSize, totalItems: 0, totalPages: 0 }); } catch (reason) { onError(errorMessage(reason, "Unable to load tickets.")); } finally { setLoading(false); } };
  useEffect(() => { Promise.all([api("/api/categories", token), api("/api/related-systems", token)]).then(([loadedCategories, loadedSystems]) => { setCategories(loadedCategories); setSystems(loadedSystems); if (loadedCategories[0]) setCategoryId(String(loadedCategories[0].id)); if (loadedSystems[0]) setSystemId(String(loadedSystems[0].id)); }).catch(() => undefined); }, [token]);
  useEffect(() => { void load(); }, [token, search, categoryFilter, systemFilter, priorityFilter, statusFilter, sort, direction, page, pageSize]);
  const resetToFirstPage = () => setPage(1);
  const create = async (event: FormEvent) => { event.preventDefault(); setCreating(true); setMessage(""); try { const data = await api("/api/tickets", token, { method: "POST", body: JSON.stringify({ categoryId: Number(categoryId), relatedSystemId: Number(systemId), summary, description, requestedPriority }) }); const created = data.ticket as Ticket; setSummary(""); setDescription(""); setMessage(`Ticket ${created.ticketNumber} created.`); if (createFile) { try { await upload(`/api/tickets/${created.id}/attachments`, token, createFile); setMessage(`Ticket ${created.ticketNumber} created with attachment.`); } catch (reason) { setMessage(`Ticket ${created.ticketNumber} created, but the attachment was not uploaded: ${safeMessage(reason, "upload failed.")}`); } setCreateFile(null); } await load(); } catch (reason) { onError(errorMessage(reason, "Unable to create the ticket.")); } finally { setCreating(false); } };
  const open = async (id: number) => { try { setSelected((await api(`/api/tickets/${id}`, token)).ticket); } catch (reason) { onError(errorMessage(reason, "Unable to load ticket.")); } };
  if (selected) return <RequesterDetail ticket={selected} token={token} onBack={() => setSelected(null)} onError={onError} onChanged={(next) => { setSelected(next); void load(); }} />;
  const totalPages = Math.max(1, pagination.totalPages || 1);
  return <section aria-labelledby="my-tickets-heading"><h1 id="my-tickets-heading" className="h3">My Tickets</h1><p className="text-secondary">Authenticated tickets belonging to your account.</p><section className="card mb-4" aria-label="Ticket filters"><div className="card-body"><div className="row g-2"><div className="col-md-4"><label className="form-label" htmlFor="requester-search">Search</label><input id="requester-search" className="form-control" placeholder="Search ticket number or summary" value={search} onChange={(event) => { setSearch(event.target.value); resetToFirstPage(); }} /></div><div className="col-md-2"><label className="form-label" htmlFor="requester-category-filter">Category</label><select id="requester-category-filter" className="form-select" value={categoryFilter} onChange={(event) => { setCategoryFilter(event.target.value); resetToFirstPage(); }}><option value="">All categories</option>{categories.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></div><div className="col-md-2"><label className="form-label" htmlFor="requester-system-filter">System</label><select id="requester-system-filter" className="form-select" value={systemFilter} onChange={(event) => { setSystemFilter(event.target.value); resetToFirstPage(); }}><option value="">All systems</option>{systems.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></div><div className="col-md-2"><label className="form-label" htmlFor="requester-priority-filter">Priority</label><select id="requester-priority-filter" className="form-select" value={priorityFilter} onChange={(event) => { setPriorityFilter(event.target.value); resetToFirstPage(); }}><option value="">All priorities</option>{PRIORITIES.map((value) => <option key={value} value={value}>{value}</option>)}</select></div><div className="col-md-2"><label className="form-label" htmlFor="requester-status-filter">Status</label><select id="requester-status-filter" className="form-select" value={statusFilter} onChange={(event) => { setStatusFilter(event.target.value); resetToFirstPage(); }}><option value="">All statuses</option>{STATUSES.map((value) => <option key={value} value={value}>{value}</option>)}</select></div><div className="col-md-3"><label className="form-label" htmlFor="requester-sort">Sort by</label><select id="requester-sort" className="form-select" value={sort} onChange={(event) => { setSort(event.target.value); resetToFirstPage(); }}><option value="createdAt">Created</option><option value="updatedAt">Updated</option><option value="ticketNumber">Ticket number</option><option value="summary">Summary</option><option value="requestedPriority">Requested priority</option></select></div><div className="col-md-2"><label className="form-label" htmlFor="requester-direction">Direction</label><select id="requester-direction" className="form-select" value={direction} onChange={(event) => { setDirection(event.target.value); resetToFirstPage(); }}><option value="desc">Newest first</option><option value="asc">Oldest first</option></select></div><div className="col-md-2"><label className="form-label" htmlFor="requester-page-size">Page size</label><select id="requester-page-size" className="form-select" value={pageSize} onChange={(event) => { setPageSize(Number(event.target.value)); resetToFirstPage(); }}><option value={10}>10</option><option value={20}>20</option><option value={50}>50</option></select></div></div></div></section>{loading && <p role="status" aria-live="polite">Loading tickets…</p>} {!loading && !items.length && <p className="text-secondary mt-3">{pagination.totalItems ? "No matching tickets." : "No tickets yet."}</p>}<div className="row g-3">{items.map((ticket) => <article className="col-12 col-md-6 ticket-card" key={ticket.id}><div className="card h-100"><div className="card-body"><button type="button" className="btn btn-link p-0" onClick={() => void open(ticket.id)} aria-label={`Open ticket ${ticket.ticketNumber}`}>{ticket.ticketNumber}</button><h2 className="h5 mt-2">{ticket.summary}</h2><p className="small text-secondary mb-2">{ticket.category?.name ?? "—"} · {ticket.relatedSystem?.name ?? "—"}</p><span className="badge text-bg-secondary me-2">{ticket.currentStatus}</span><span className="badge text-bg-success">{ticket.requestedPriority}</span></div></div></article>)}</div><nav className="d-flex flex-wrap justify-content-between align-items-center gap-2 mt-3" aria-label="Ticket pages"><span className="text-secondary small">{pagination.totalItems} tickets</span><div className="btn-group"><button type="button" className="btn btn-toktickit-outline" disabled={page <= 1 || loading} onClick={() => setPage(page - 1)}>Previous</button><span className="btn btn-light disabled">Page {page} of {totalPages}</span><button type="button" className="btn btn-toktickit-outline" disabled={page >= totalPages || loading} onClick={() => setPage(page + 1)}>Next</button></div></nav><form className="card mt-4" onSubmit={create} aria-labelledby="create-ticket-heading" aria-busy={creating}><div className="card-body"><h2 id="create-ticket-heading" className="h5">Create ticket</h2><div className="row g-2"><div className="col-md-6"><label className="form-label" htmlFor="ticket-category">Category</label><select id="ticket-category" className="form-select" required value={categoryId} onChange={(event) => setCategoryId(event.target.value)}><option value="">Choose a category</option>{categories.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></div><div className="col-md-6"><label className="form-label" htmlFor="ticket-system">Related system</label><select id="ticket-system" className="form-select" required value={systemId} onChange={(event) => setSystemId(event.target.value)}><option value="">Choose a related system</option>{systems.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></div><div className="col-md-6"><label className="form-label" htmlFor="ticket-priority">Requested priority</label><select id="ticket-priority" className="form-select" required value={requestedPriority} onChange={(event) => setRequestedPriority(event.target.value)}><option value="">Choose a priority</option>{PRIORITIES.map((value) => <option key={value} value={value}>{value}</option>)}</select></div><div className="col-12"><label className="form-label" htmlFor="requester-summary">Summary</label><input id="requester-summary" className="form-control" required minLength={5} maxLength={160} value={summary} onChange={(event) => setSummary(event.target.value)} /></div><div className="col-12"><label className="form-label" htmlFor="requester-description">Description</label><textarea id="requester-description" className="form-control" required minLength={10} maxLength={5000} rows={4} value={description} onChange={(event) => setDescription(event.target.value)} /></div><div className="col-12"><label className="form-label" htmlFor="requester-attachment">Attachment</label><input id="requester-attachment" className="form-control" type="file" accept=".jpg,.jpeg,.png,.webp,.pdf" onChange={(event) => setCreateFile(event.target.files?.[0] ?? null)} /><div className="form-text">Optional: JPG, PNG, WEBP, or PDF up to 5 MB.</div></div></div>{message && <div className="alert alert-success mt-3" role="status">{message}</div>}<button type="submit" className="btn btn-toktickit-primary mt-3" disabled={creating}>{creating ? "Creating ticket…" : "Create ticket"}</button></div></form></section>;
}

function RequesterDetail({ ticket, token, onBack, onError, onChanged }: { ticket: Ticket; token: string; onBack: () => void; onError: (message: string) => void; onChanged: (ticket: Ticket) => void }) {
  const [comment, setComment] = useState(""); const [file, setFile] = useState<File | null>(null); const [busy, setBusy] = useState(false); const [commentBusy, setCommentBusy] = useState(false); const [resolutionBusy, setResolutionBusy] = useState(false);
  const refresh = async () => { try { onChanged((await api(`/api/tickets/${ticket.id}`, token)).ticket); } catch (reason) { onError(errorMessage(reason, "Unable to refresh ticket.")); } };
  const addComment = async (event: FormEvent) => { event.preventDefault(); setCommentBusy(true); try { await api(`/api/tickets/${ticket.id}/comments`, token, { method: "POST", body: JSON.stringify({ content: comment }) }); setComment(""); await refresh(); } catch (reason) { onError(errorMessage(reason, "Unable to add comment.")); } finally { setCommentBusy(false); } };
  const reportResolved = async () => { setResolutionBusy(true); try { await api(`/api/tickets/${ticket.id}/resolution-signal`, token, { method: "POST" }); await refresh(); } catch (reason) { onError(errorMessage(reason, "Unable to report resolution.")); } finally { setResolutionBusy(false); } };
  const addAttachment = async () => { if (!file) return; setBusy(true); try { await upload(`/api/tickets/${ticket.id}/attachments`, token, file); setFile(null); await refresh(); } catch (reason) { onError(errorMessage(reason, "Unable to upload attachment.")); } finally { setBusy(false); } };
  const download = async (attachment: Attachment) => { try { const response = await fetch(`${API}/api/attachments/${attachment.id}/download`, { headers: { Authorization: `Bearer ${token}` } }); if (!response.ok) throw new Error("Unable to download attachment."); const url = URL.createObjectURL(await response.blob()); const link = document.createElement("a"); link.href = url; link.download = attachment.originalFilename; link.click(); URL.revokeObjectURL(url); } catch (reason) { onError(safeMessage(reason, "Unable to download attachment.")); } };
  const remove = async (attachmentId: number) => { const reason = window.prompt("Why should this attachment be removed?", "No longer needed"); if (!reason) return; setBusy(true); try { await api(`/api/attachments/${attachmentId}`, token, { method: "DELETE", body: JSON.stringify({ removalReason: reason }) }); await refresh(); } catch (error) { onError(errorMessage(error, "Unable to remove attachment.")); } finally { setBusy(false); } };
  return <section className="card shadow-sm border-0" aria-labelledby="requester-ticket-detail-heading"><div className="card-body p-4"><button type="button" className="btn btn-toktickit-outline mb-3" onClick={onBack}>Back to My Tickets</button><h1 id="requester-ticket-detail-heading" className="h3">Ticket Detail</h1><h2 className="h5 mt-3">{ticket.ticketNumber}</h2><p className="text-secondary">{ticket.category?.name} · {ticket.relatedSystem?.name} · {ticket.currentStatus}</p><p><strong>Summary:</strong> {ticket.summary}</p><p>{ticket.description}</p>{ticket.problemAppearsResolvedAt ? <div className="alert alert-success mb-4" role="status">You reported that this problem appears resolved.</div> : <button type="button" className="btn btn-outline-success mb-4" disabled={resolutionBusy} onClick={() => void reportResolved()}>{resolutionBusy ? "Recording…" : "Problem Appears Resolved"}</button>}<section aria-labelledby="requester-attachments"><h2 id="requester-attachments" className="h5">Attachments</h2><div className="d-flex gap-2 mb-2"><input aria-label="Attachment file" className="form-control" type="file" accept=".jpg,.jpeg,.png,.webp,.pdf" onChange={(event) => setFile(event.target.files?.[0] ?? null)} /><button type="button" className="btn btn-toktickit-primary" disabled={!file || busy} onClick={() => void addAttachment()}>{busy ? "Uploading…" : "Upload"}</button></div><ul className="list-group mb-4">{(ticket.attachments ?? []).map((attachment) => <li className="list-group-item d-flex flex-wrap gap-2 align-items-center" key={attachment.id}><span className="me-auto">{attachment.originalFilename}</span>{attachment.removedAt ? <span className="badge text-bg-secondary">Removed</span> : <><button type="button" className="btn btn-sm btn-toktickit-outline" onClick={() => void download(attachment)}>Download</button><button type="button" className="btn btn-sm btn-outline-danger" disabled={busy} onClick={() => void remove(attachment.id)}>Remove</button></>}</li>)}</ul></section><section aria-labelledby="requester-comments"><h2 id="requester-comments" className="h5">Public comments</h2><ul className="list-group mb-3">{(ticket.publicComments ?? []).map((item) => <li className="list-group-item" key={item.id}><strong>{item.author?.name ?? "User"}</strong>: {item.content}</li>)}</ul><form onSubmit={addComment} aria-busy={commentBusy}><div className="input-group"><input className="form-control" required minLength={1} maxLength={2000} aria-label="Public comment" placeholder="Add a public comment" value={comment} onChange={(event) => setComment(event.target.value)} /><button type="submit" className="btn btn-toktickit-primary" disabled={commentBusy}>{commentBusy ? "Commenting…" : "Comment"}</button></div></form></section></div></section>;
}

function Queue({ token }: { token: string }) {
  const [items, setItems] = useState<QueueItem[]>([]); const [selectedId, setSelectedId] = useState<number | null>(null); const [search, setSearch] = useState(""); const [status, setStatus] = useState(""); const [owner, setOwner] = useState(""); const [requestedPriority, setRequestedPriority] = useState(""); const [itPriority, setItPriority] = useState(""); const [categoryId, setCategoryId] = useState(""); const [requesterId, setRequesterId] = useState(""); const [sort, setSort] = useState("updatedAt"); const [direction, setDirection] = useState("desc"); const [page, setPage] = useState(1); const [pageSize, setPageSize] = useState(10); const [pagination, setPagination] = useState<Pagination>({ page: 1, pageSize: 10, totalItems: 0, totalPages: 0 }); const [staff, setStaff] = useState<User[]>([]); const [categories, setCategories] = useState<Reference[]>([]); const [counts, setCounts] = useState<any>(null); const [loading, setLoading] = useState(false); const [loadError, setLoadError] = useState("");
  const load = async () => { setLoading(true); setLoadError(""); try { const params = new URLSearchParams({ page: String(page), pageSize: String(pageSize), sort, direction }); if (search.trim()) params.set("search", search.trim()); if (status) params.set("status", status); if (owner) params.set("ownerUserId", owner === "unassigned" ? "null" : owner); if (requestedPriority) params.set("requestedPriority", requestedPriority); if (itPriority) params.set("itPriority", itPriority); if (categoryId) params.set("categoryId", categoryId); if (requesterId.trim()) params.set("requesterId", requesterId.trim()); const data = await api(`/api/staff/tickets?${params.toString()}`, token); setItems(data.items ?? []); setPagination(data.pagination ?? { page, pageSize, totalItems: 0, totalPages: 0 }); setCounts(data.counts ?? null); } catch (reason) { setLoadError(errorMessage(reason, "Unable to load the ticket queue.")); } finally { setLoading(false); } };
  useEffect(() => { void load(); }, [token, search, status, owner, requestedPriority, itPriority, categoryId, requesterId, sort, direction, page, pageSize]);
  useEffect(() => { Promise.all([api("/api/staff/users", token), api("/api/categories", token)]).then(([loadedStaff, loadedCategories]) => { setStaff(loadedStaff); setCategories(loadedCategories); }).catch(() => undefined); }, [token]);
  if (selectedId !== null) return <StaffDetail token={token} ticketId={selectedId} staff={staff} onBack={() => setSelectedId(null)} onChanged={() => { void load(); }} />;
  const clear = () => { setSearch(""); setStatus(""); setOwner(""); setRequestedPriority(""); setItPriority(""); setCategoryId(""); setRequesterId(""); setSort("updatedAt"); setDirection("desc"); setPage(1); setPageSize(10); };
  const totalPages = Math.max(1, pagination.totalPages || 1);
  return <section aria-labelledby="queue-heading"><h1 id="queue-heading" className="h3">Ticket Queue</h1><p className="text-secondary">Search, filter, claim, assign, and work tickets assigned to the IT team.</p><section className="card mb-4" aria-label="Queue filters"><div className="card-body"><div className="row g-2"><div className="col-12 col-lg-4"><label className="form-label" htmlFor="queue-search">Search</label><input id="queue-search" className="form-control" placeholder="Ticket number or summary" value={search} onChange={(event) => { setSearch(event.target.value); setPage(1); }} /></div><div className="col-6 col-lg-2"><label className="form-label" htmlFor="queue-status">Status</label><select id="queue-status" className="form-select" value={status} onChange={(event) => { setStatus(event.target.value); setPage(1); }}><option value="">All statuses</option>{STATUSES.map((value) => <option key={value} value={value}>{value}</option>)}</select></div><div className="col-6 col-lg-2"><label className="form-label" htmlFor="queue-owner">Owner</label><select id="queue-owner" className="form-select" value={owner} onChange={(event) => { setOwner(event.target.value); setPage(1); }}><option value="">All owners</option><option value="unassigned">Unassigned</option>{staff.map((person) => <option key={person.id} value={person.id}>{person.name}</option>)}</select></div><div className="col-6 col-lg-2"><label className="form-label" htmlFor="queue-requested-priority">Requested priority</label><select id="queue-requested-priority" className="form-select" value={requestedPriority} onChange={(event) => { setRequestedPriority(event.target.value); setPage(1); }}><option value="">All priorities</option>{PRIORITIES.map((value) => <option key={value} value={value}>{value}</option>)}</select></div><div className="col-6 col-lg-2"><label className="form-label" htmlFor="queue-it-priority">IT priority</label><select id="queue-it-priority" className="form-select" value={itPriority} onChange={(event) => { setItPriority(event.target.value); setPage(1); }}><option value="">All priorities</option>{PRIORITIES.map((value) => <option key={value} value={value}>{value}</option>)}</select></div><div className="col-6 col-lg-3"><label className="form-label" htmlFor="queue-category">Category</label><select id="queue-category" className="form-select" value={categoryId} onChange={(event) => { setCategoryId(event.target.value); setPage(1); }}><option value="">All categories</option>{categories.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></div><div className="col-6 col-lg-3"><label className="form-label" htmlFor="queue-requester">Requester ID</label><input id="queue-requester" className="form-control" inputMode="numeric" value={requesterId} onChange={(event) => { setRequesterId(event.target.value.replace(/\D/g, "")); setPage(1); }} /></div><div className="col-6 col-lg-2"><label className="form-label" htmlFor="queue-sort">Sort by</label><select id="queue-sort" className="form-select" value={sort} onChange={(event) => { setSort(event.target.value); setPage(1); }}><option value="updatedAt">Updated</option><option value="createdAt">Created</option><option value="ticketNumber">Ticket number</option><option value="summary">Summary</option><option value="currentStatus">Status</option><option value="itPriority">IT priority</option><option value="requestedPriority">Requested priority</option></select></div><div className="col-6 col-lg-2"><label className="form-label" htmlFor="queue-direction">Direction</label><select id="queue-direction" className="form-select" value={direction} onChange={(event) => { setDirection(event.target.value); setPage(1); }}><option value="desc">Descending</option><option value="asc">Ascending</option></select></div><div className="col-6 col-lg-2"><label className="form-label" htmlFor="queue-page-size">Page size</label><select id="queue-page-size" className="form-select" value={pageSize} onChange={(event) => { setPageSize(Number(event.target.value)); setPage(1); }}><option value={10}>10</option><option value={20}>20</option><option value={50}>50</option></select></div><div className="col-12 col-lg-2 d-flex align-items-end"><button type="button" className="btn btn-outline-secondary w-100" onClick={clear}>Clear filters</button></div></div></div></section>{counts && <div className="alert toktickit-context" role="status"><strong>{counts.totalItems} matching tickets</strong> · {counts.unassigned} unassigned · {counts.byItPriority?.HIGH ?? 0} high IT priority</div>}{loading && <p role="status" aria-live="polite">Loading ticket queue…</p>}{loadError && <div className="alert alert-danger" role="alert">{loadError}<button type="button" className="btn btn-sm btn-outline-danger ms-2" onClick={() => void load()}>Retry</button></div>}{!loading && !loadError && !items.length && <p className="text-secondary">{pagination.totalItems ? "No matching tickets." : "No tickets in the queue."}</p>}<div className="table-responsive-lg"><table className="table table-sm align-middle d-none d-lg-table"><thead><tr><th>Ticket Number</th><th>Created</th><th>Updated</th><th>Summary</th><th>Requester</th><th>Category</th><th>Requested Priority</th><th>IT Priority</th><th>Status</th><th>Owner</th><th>Open</th></tr></thead><tbody>{items.map((ticket) => <tr key={ticket.id}><td>{ticket.ticketNumber}</td><td>{formatDate(ticket.createdAt)}</td><td>{formatDate(ticket.updatedAt)}</td><td>{ticket.summary}</td><td>{ticket.requester?.name ?? "—"}</td><td>{ticket.category?.name ?? "—"}</td><td>{ticket.requestedPriority}</td><td>{ticket.itPriority}</td><td><span className="badge text-bg-secondary">{ticket.currentStatus}</span></td><td>{ticket.owner?.name ?? "Unassigned"}</td><td><button type="button" className="btn btn-sm btn-toktickit-outline" onClick={() => setSelectedId(ticket.id)} aria-label={`Open ${ticket.ticketNumber}`}>Open</button></td></tr>)}</tbody></table></div><div className="d-lg-none">{items.map((ticket) => <article className="card queue-card mb-3" key={ticket.id}><div className="card-body"><div className="d-flex justify-content-between gap-2"><strong>{ticket.ticketNumber}</strong><span className="badge text-bg-secondary">{ticket.currentStatus}</span></div><h2 className="h5 mt-2">{ticket.summary}</h2><dl className="row small mb-3"><dt className="col-5">Created</dt><dd className="col-7">{formatDate(ticket.createdAt)}</dd><dt className="col-5">Updated</dt><dd className="col-7">{formatDate(ticket.updatedAt)}</dd><dt className="col-5">Requester</dt><dd className="col-7">{ticket.requester?.name ?? "—"}</dd><dt className="col-5">Category</dt><dd className="col-7">{ticket.category?.name ?? "—"}</dd><dt className="col-5">Requested priority</dt><dd className="col-7">{ticket.requestedPriority}</dd><dt className="col-5">IT priority</dt><dd className="col-7">{ticket.itPriority}</dd><dt className="col-5">Owner</dt><dd className="col-7">{ticket.owner?.name ?? "Unassigned"}</dd></dl><button type="button" className="btn btn-toktickit-outline w-100" onClick={() => setSelectedId(ticket.id)} aria-label={`Open ${ticket.ticketNumber}`}>Open ticket</button></div></article>)}</div><nav className="d-flex flex-wrap justify-content-between align-items-center gap-2 mt-3" aria-label="Queue pages"><span className="text-secondary small">{pagination.totalItems} tickets</span><div className="btn-group"><button type="button" className="btn btn-toktickit-outline" disabled={page <= 1 || loading} onClick={() => setPage(page - 1)}>Previous</button><span className="btn btn-light disabled">Page {page} of {totalPages}</span><button type="button" className="btn btn-toktickit-outline" disabled={page >= totalPages || loading} onClick={() => setPage(page + 1)}>Next</button></div></nav></section>;
}

function StaffDetail({ token, ticketId, staff, onBack, onChanged }: { token: string; ticketId: number; staff: User[]; onBack: () => void; onChanged: () => void }) {
  const [ticket, setTicket] = useState<Ticket | null>(null); const [comment, setComment] = useState(""); const [note, setNote] = useState(""); const [status, setStatus] = useState(""); const [priority, setPriority] = useState(""); const [loading, setLoading] = useState(true); const [loadError, setLoadError] = useState(""); const [busy, setBusy] = useState(false); const [commentBusy, setCommentBusy] = useState(false); const [noteBusy, setNoteBusy] = useState(false);
  const load = async () => { setLoading(true); setLoadError(""); try { const data = await api(`/api/staff/tickets/${ticketId}`, token); setTicket(data.ticket); setStatus(data.ticket.currentStatus); setPriority(data.ticket.itPriority); } catch (reason) { setLoadError(errorMessage(reason, "Unable to load ticket detail.")); } finally { setLoading(false); } };
  useEffect(() => { void load(); }, [ticketId, token]);
  const update = async (path: string, body: Record<string, unknown>) => { setBusy(true); try { await api(`/api/staff/tickets/${ticketId}/${path}`, token, { method: path === "claim" ? "POST" : "PATCH", body: JSON.stringify(body) }); await load(); onChanged(); } catch (reason) { setLoadError(errorMessage(reason, "Unable to update ticket.")); } finally { setBusy(false); } };
  const add = async (kind: "comments" | "notes", content: string, clear: () => void) => { const setBusyState = kind === "comments" ? setCommentBusy : setNoteBusy; setBusyState(true); try { await api(`/api/staff/tickets/${ticketId}/${kind}`, token, { method: "POST", body: JSON.stringify({ content }) }); clear(); await load(); } catch (reason) { setLoadError(errorMessage(reason, "Unable to add ticket update.")); } finally { setBusyState(false); } };
  const download = async (attachment: Attachment) => { try { const response = await fetch(`${API}/api/staff/attachments/${attachment.id}/download`, { headers: { Authorization: `Bearer ${token}` } }); if (!response.ok) throw new Error("Unable to download attachment."); const url = URL.createObjectURL(await response.blob()); const link = document.createElement("a"); link.href = url; link.download = attachment.originalFilename; link.click(); URL.revokeObjectURL(url); } catch (reason) { setLoadError(safeMessage(reason, "Unable to download attachment.")); } };
  if (loading) return <p role="status" aria-live="polite">Loading ticket detail…</p>;
  if (loadError && !ticket) return <section><div className="alert alert-danger" role="alert">{loadError}<button type="button" className="btn btn-sm btn-outline-danger ms-2" onClick={() => void load()}>Retry</button></div><button type="button" className="btn btn-toktickit-outline" onClick={onBack}>Back to Queue</button></section>;
  if (!ticket) return null;
  return <section className="card shadow-sm border-0" aria-labelledby="staff-ticket-detail-heading"><div className="card-body p-4"><button type="button" className="btn btn-toktickit-outline mb-3" onClick={onBack}>Back to Queue</button><h1 id="staff-ticket-detail-heading" className="h3">Staff Ticket Detail</h1><h2 className="h5 mt-3">{ticket.ticketNumber}</h2>{loadError && <div className="alert alert-danger" role="alert">{loadError}</div>}<section aria-labelledby="staff-ticket-information"><h2 id="staff-ticket-information" className="h5">Ticket information</h2><dl className="row"><dt className="col-sm-3">Summary</dt><dd className="col-sm-9">{ticket.summary}</dd><dt className="col-sm-3">Requester</dt><dd className="col-sm-9">{ticket.requester?.name ?? "—"} {ticket.requester?.email ? `(${ticket.requester.email})` : ""}</dd><dt className="col-sm-3">Category</dt><dd className="col-sm-9">{ticket.category?.name ?? "—"}</dd><dt className="col-sm-3">Related system</dt><dd className="col-sm-9">{ticket.relatedSystem?.name ?? "—"}</dd><dt className="col-sm-3">Description</dt><dd className="col-sm-9">{ticket.description}</dd></dl></section><section className="border-top pt-3" aria-labelledby="staff-ticket-controls"><h2 id="staff-ticket-controls" className="h5">Ownership, priority, and status</h2><div className="row g-3"><div className="col-md-4"><label className="form-label" htmlFor="staff-status">Workflow status</label><select id="staff-status" className="form-select" value={status} disabled={busy} onChange={(event) => { setStatus(event.target.value); void update("status", { currentStatus: event.target.value }); }}>{STATUSES.map((value) => <option key={value} value={value}>{value}</option>)}</select></div><div className="col-md-4"><label className="form-label" htmlFor="staff-priority">IT priority</label><select id="staff-priority" className="form-select" value={priority} disabled={busy} onChange={(event) => { setPriority(event.target.value); void update("priority", { itPriority: event.target.value }); }}>{PRIORITIES.map((value) => <option key={value} value={value}>{value}</option>)}</select></div><div className="col-md-4"><label className="form-label" htmlFor="staff-owner">Owner</label><select id="staff-owner" className="form-select" value={ticket.owner?.id ?? ""} disabled={busy} onChange={(event) => void update("owner", { ownerUserId: event.target.value ? Number(event.target.value) : null })}><option value="">Unassigned</option>{staff.map((person) => <option key={person.id} value={person.id}>{person.name}</option>)}</select></div><div className="col-12"><button type="button" className="btn btn-toktickit-primary" disabled={busy || Boolean(ticket.owner)} onClick={() => void update("claim", {})}>{busy ? "Updating…" : ticket.owner ? "Already assigned" : "Claim ticket"}</button></div></div></section><section className="border-top pt-3 mt-4" aria-labelledby="staff-attachments"><h2 id="staff-attachments" className="h5">Attachments</h2>{!(ticket.attachments ?? []).length && <p className="text-secondary">No attachments.</p>}<ul className="list-group">{(ticket.attachments ?? []).map((attachment) => <li className="list-group-item d-flex flex-wrap gap-2 align-items-center" key={attachment.id}><span className="me-auto">{attachment.originalFilename}</span>{attachment.removedAt ? <span className="badge text-bg-secondary">Removed</span> : <button type="button" className="btn btn-sm btn-toktickit-outline" onClick={() => void download(attachment)}>Download attachment</button>}</li>)}</ul></section><section className="border-top pt-3 mt-4" aria-labelledby="staff-public-comments"><h2 id="staff-public-comments" className="h5">Public comments</h2><ul className="list-group mb-3">{(ticket.publicComments ?? []).map((item) => <li className="list-group-item" key={item.id}>{item.author?.name ?? "User"}: {item.content}</li>)}</ul><form onSubmit={(event) => { event.preventDefault(); void add("comments", comment, () => setComment("")); }} aria-busy={commentBusy}><div className="input-group"><input className="form-control" required maxLength={2000} aria-label="Staff public comment" value={comment} onChange={(event) => setComment(event.target.value)} placeholder="Add public comment" /><button type="submit" className="btn btn-toktickit-primary" disabled={commentBusy}>{commentBusy ? "Commenting…" : "Comment"}</button></div></form></section><section className="border-top pt-3 mt-4" aria-labelledby="staff-internal-notes"><h2 id="staff-internal-notes" className="h5">Internal notes</h2><ul className="list-group mb-3">{(ticket.internalNotes ?? []).map((item) => <li className="list-group-item" key={item.id}>{item.author?.name ?? "Staff"}: {item.content}</li>)}</ul><form onSubmit={(event) => { event.preventDefault(); void add("notes", note, () => setNote("")); }} aria-busy={noteBusy}><div className="input-group"><input className="form-control" required maxLength={2000} aria-label="Internal note" value={note} onChange={(event) => setNote(event.target.value)} placeholder="Add internal note" /><button type="submit" className="btn btn-toktickit-outline" disabled={noteBusy}>{noteBusy ? "Saving…" : "Add note"}</button></div></form></section></div></section>;
}

function Users({ token, onError }: { token: string; onError: (message: string) => void }) {
  const [users, setUsers] = useState<User[]>([]); const [search, setSearch] = useState(""); const [roleFilter, setRoleFilter] = useState(""); const [name, setName] = useState(""); const [email, setEmail] = useState(""); const [role, setRole] = useState<Role>("REQUESTER"); const [initialPassword, setInitialPassword] = useState(""); const [isActive, setIsActive] = useState(true); const [message, setMessage] = useState(""); const [loading, setLoading] = useState(false); const [creating, setCreating] = useState(false); const [loadError, setLoadError] = useState("");
  const load = async () => { setLoading(true); setLoadError(""); try { const params = new URLSearchParams(); if (search.trim()) params.set("search", search.trim()); if (roleFilter) params.set("role", roleFilter); const data = await api(`/api/admin/users?${params.toString()}`, token); setUsers(data.items ?? []); } catch (reason) { setLoadError(errorMessage(reason, "Unable to load users.")); } finally { setLoading(false); } };
  useEffect(() => { void load(); }, [token, search, roleFilter]);
  const create = async (event: FormEvent) => { event.preventDefault(); setCreating(true); setMessage(""); try { await api("/api/admin/users", token, { method: "POST", body: JSON.stringify({ name, email, role, initialPassword, isActive }) }); setName(""); setEmail(""); setInitialPassword(""); setMessage("User created with a required first-login password change."); await load(); } catch (reason) { onError(errorMessage(reason, "Unable to create the user.")); } finally { setCreating(false); } };
  const update = async (id: number, body: Record<string, unknown>) => { try { await api(`/api/admin/users/${id}`, token, { method: "PATCH", body: JSON.stringify(body) }); setMessage("User updated."); await load(); } catch (reason) { onError(errorMessage(reason, "Unable to update the user.")); } };
  const resetPassword = async (id: number) => { const password = window.prompt("New initial password (12+ mixed-case/numeric characters)"); if (!password) return; try { await api(`/api/admin/users/${id}/initial-password`, token, { method: "POST", body: JSON.stringify({ initialPassword: password }) }); setMessage("Initial password reset; the user must change it at first login."); } catch (reason) { onError(errorMessage(reason, "Unable to reset the initial password.")); } };
  return <section aria-labelledby="users-heading"><h1 id="users-heading" className="h3">User Management</h1><section className="card mb-4" aria-label="User filters"><div className="card-body"><div className="row g-2"><div className="col-md-8"><label className="form-label" htmlFor="user-search">Search name or email</label><input id="user-search" className="form-control" value={search} onChange={(event) => setSearch(event.target.value)} /></div><div className="col-md-4"><label className="form-label" htmlFor="user-role-filter">Role</label><select id="user-role-filter" className="form-select" value={roleFilter} onChange={(event) => setRoleFilter(event.target.value)}><option value="">All roles</option>{ROLES.map((value) => <option key={value} value={value}>{value}</option>)}</select></div></div></div></section>{loading && <p role="status" aria-live="polite">Loading users…</p>}{loadError && <div className="alert alert-danger" role="alert">{loadError}<button type="button" className="btn btn-sm btn-outline-danger ms-2" onClick={() => void load()}>Retry</button></div>}{!loading && !loadError && !users.length && <p className="text-secondary">No matching users.</p>}<table className="table align-middle d-none d-lg-table"><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th>Edit</th></tr></thead><tbody>{users.map((user) => <UserRow key={user.id} user={user} onSave={(body) => update(user.id, body)} onToggle={() => void update(user.id, { isActive: !user.isActive })} onReset={() => void resetPassword(user.id)} />)}</tbody></table><div className="d-lg-none">{users.map((user) => <UserCard key={user.id} user={user} onSave={(body) => update(user.id, body)} onToggle={() => void update(user.id, { isActive: !user.isActive })} onReset={() => void resetPassword(user.id)} />)}</div><form className="card mt-4" onSubmit={create} aria-labelledby="create-user-heading" aria-busy={creating}><div className="card-body"><h2 id="create-user-heading" className="h5">Create user</h2><div className="row g-2"><div className="col-md-3"><label className="form-label" htmlFor="new-user-name">Name</label><input id="new-user-name" className="form-control" required minLength={2} value={name} onChange={(event) => setName(event.target.value)} /></div><div className="col-md-3"><label className="form-label" htmlFor="new-user-email">Email</label><input id="new-user-email" className="form-control" required type="email" value={email} onChange={(event) => setEmail(event.target.value)} /></div><div className="col-md-2"><label className="form-label" htmlFor="new-user-role">Role</label><select id="new-user-role" className="form-select" value={role} onChange={(event) => setRole(event.target.value as Role)}>{ROLES.map((value) => <option key={value} value={value}>{value}</option>)}</select></div><div className="col-md-3"><label className="form-label" htmlFor="new-user-password">Initial password</label><input id="new-user-password" className="form-control" required minLength={12} type="password" value={initialPassword} onChange={(event) => setInitialPassword(event.target.value)} /><div className="form-text">12+ characters with upper-case, lower-case, and a number.</div></div><div className="col-md-1 d-flex align-items-end"><button type="submit" className="btn btn-toktickit-primary" disabled={creating}>{creating ? "Adding…" : "Add"}</button></div></div><div className="form-check mt-3"><input id="new-user-active" className="form-check-input" type="checkbox" checked={isActive} onChange={(event) => setIsActive(event.target.checked)} /><label className="form-check-label" htmlFor="new-user-active">Active account</label></div>{message && <div className="text-success mt-3" role="status">{message}</div>}</div></form></section>;
}

function UserRow({ user, onSave, onToggle, onReset }: { user: User; onSave: (body: Record<string, unknown>) => Promise<void>; onToggle: () => void; onReset: () => void }) {
  const [name, setName] = useState(user.name); const [email, setEmail] = useState(user.email); const [role, setRole] = useState(user.role); const [busy, setBusy] = useState(false);
  useEffect(() => { setName(user.name); setEmail(user.email); setRole(user.role); }, [user]);
  const save = async () => { setBusy(true); try { await onSave({ name, email, role }); } finally { setBusy(false); } };
  return <tr><td><label className="visually-hidden" htmlFor={`user-name-${user.id}`}>Name for {user.email}</label><input id={`user-name-${user.id}`} className="form-control form-control-sm" value={name} onChange={(event) => setName(event.target.value)} /></td><td><label className="visually-hidden" htmlFor={`user-email-${user.id}`}>Email for {user.name}</label><input id={`user-email-${user.id}`} className="form-control form-control-sm" type="email" value={email} onChange={(event) => setEmail(event.target.value)} /></td><td><label className="visually-hidden" htmlFor={`user-role-${user.id}`}>Role for {user.name}</label><select id={`user-role-${user.id}`} className="form-select form-select-sm" value={role} onChange={(event) => setRole(event.target.value as Role)}>{ROLES.map((value) => <option key={value} value={value}>{value}</option>)}</select></td><td>{user.isActive ? "Active" : "Inactive"}</td><td><div className="d-flex flex-wrap gap-1"><button type="button" className="btn btn-sm btn-toktickit-primary" disabled={busy} onClick={() => void save()}>{busy ? "Saving…" : "Save changes"}</button><button type="button" className="btn btn-sm btn-outline-secondary" onClick={onToggle}>{user.isActive ? "Deactivate" : "Reactivate"}</button><button type="button" className="btn btn-sm btn-outline-secondary" onClick={onReset}>Reset password</button></div></td></tr>;
}

function UserCard({ user, onSave, onToggle, onReset }: { user: User; onSave: (body: Record<string, unknown>) => Promise<void>; onToggle: () => void; onReset: () => void }) {
  const [name, setName] = useState(user.name); const [email, setEmail] = useState(user.email); const [role, setRole] = useState(user.role); const [busy, setBusy] = useState(false);
  useEffect(() => { setName(user.name); setEmail(user.email); setRole(user.role); }, [user]);
  const save = async () => { setBusy(true); try { await onSave({ name, email, role }); } finally { setBusy(false); } };
  return <article className="card user-card mb-3"><div className="card-body"><h2 className="h5">{user.name}</h2><div className="mb-2"><label className="form-label" htmlFor={`mobile-user-name-${user.id}`}>Name</label><input id={`mobile-user-name-${user.id}`} className="form-control" value={name} onChange={(event) => setName(event.target.value)} /></div><div className="mb-2"><label className="form-label" htmlFor={`mobile-user-email-${user.id}`}>Email</label><input id={`mobile-user-email-${user.id}`} className="form-control" type="email" value={email} onChange={(event) => setEmail(event.target.value)} /></div><div className="mb-2"><label className="form-label" htmlFor={`mobile-user-role-${user.id}`}>Role</label><select id={`mobile-user-role-${user.id}`} className="form-select" value={role} onChange={(event) => setRole(event.target.value as Role)}>{ROLES.map((value) => <option key={value} value={value}>{value}</option>)}</select></div><p className="mb-3">Status: <strong>{user.isActive ? "Active" : "Inactive"}</strong></p><div className="d-flex flex-wrap gap-2"><button type="button" className="btn btn-toktickit-primary" disabled={busy} onClick={() => void save()}>{busy ? "Saving…" : "Save changes"}</button><button type="button" className="btn btn-outline-secondary" onClick={onToggle}>{user.isActive ? "Deactivate" : "Reactivate"}</button><button type="button" className="btn btn-outline-secondary" onClick={onReset}>Reset password</button></div></div></article>;
}
